-- 1.3 issuers. Nome: CrpnNm do Cadastro de Instrumentos da B3 de 30/10/2026, arquivo "Final"
--   (data/raw/b3-instrumentos/InstrumentsConsolidatedFile_20261030.csv).
-- Companhias: CNPJ e código CVM do cadastro de companhias abertas da CVM, situação ATIVO
--   (https://dados.cvm.gov.br/dados/CIA_ABERTA/CAD/DADOS/cad_cia_aberta.csv, data/raw/cvm-cia/); segmento da planilha da B3.
-- FIIs: CNPJ do informe mensal de FII da CVM, arquivo geral, referência 09/2026 (fontes-poc.md, arquivo extra).
-- ETFs: CNPJ do registro de fundos da CVM (data/raw/cvm-fundos/registro_fundo_classe/registro_fundo.csv).
-- Estrangeiros (BDR) sem CNPJ nem código CVM (não estão no cad_cia_aberta, que é de companhias nacionais); os de BDR
-- patrocinado (AURA, JBSS) têm segmento na planilha da B3. Fundos, estrangeiros de BDR não patrocinado e o Tesouro
-- ficam sem setor (emissor sem setor, caso de LEFT JOIN).
-- Chave natural: cnpj (UNIQUE) e o nome (NOT EXISTS), porque o K5 cria emissores pelo nome do Cadastro, sem CNPJ.
-- Emissor que a carga do K5 já criou mantém o id e recebe CNPJ, código CVM e setor do seed; os ativos de 1.6 e 1.7
-- acham o emissor pela chave natural, por meio da visão temporária seed_issuer (BD-2).
